local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["e709312bef16c64b"] = { "L'anziana Preda Cielo osserva le ⟦Westfall=Marche Occidentali⟧ dall'alto di ⟦Sentinel Hill=Guardiacolle⟧.", "." },
  ["e70fe75e3dbc0937"] = { "Dover combattere contro la mia stessa gente mi rattrista profondamente.", "." },
  ["e717bcbda393680e"] = { "Quindi la ⟦Searing Blade=Lama Rovente⟧ è sacrificabile?", "." },
  ["e7188a853f31f07c"] = { "Pane caldo e genuino!", "." },
  ["e71ca7f38c75d641"] = { "È deciso. Comando io la ⟦Might of Kalimdor=Forza di Kalimdor⟧. Assicurati che i tuoi soldati lo capiscano e lo accettino come un dato di fatto. Di sangue se n'è già versato in abbondanza. Che non se ne versi tra le nostre fazioni.", "." },
  ["e71cad732fd10f64"] = { "Sono un uomo semplice che sa qualcosa di sartoria, ma ti serve più aiuto di quanto io possa darti. Ho sentito parlare di un Elfo della Notte che è un sarto molto abile. Vive a ⟦Stormwind=Roccavento⟧, nel Quartiere della Magia.", "." },
  ["e722551b0171fcd0"] = { "Con quella faccia, meglio che tenga d'occhio il borsellino. Posso aiutarti in qualcosa?", "." },
  ["e726247cf416b943"] = { "Marketing - Saluto per il riscatto iCoke (confezione regalo S.H.E.)", "." },
  ["e7350f25bc6a8614"] = { "E ora, se aggiungo quelli gialli...", "." },
  ["e7379578ee4c0f51"] = { "E mentre il tuo corpo inerte penzolerà dalle travi, godrò nel sapere che un pazzo è stato messo a morte. Dopotutto, che prove hai? Ti aspettavi di entrare qui, puntare il dito contro la nobiltà e andartene <illeso/illesa>?", "." },
  ["e73acaf106325915"] = { "Stiamo avendo la meglio sul Flagello: gli effetti della peste alterata lo colpiranno ancora per almeno un giorno intero! Però dobbiamo restare all'erta, quindi sabota un calderone appena puoi.", "." },
  ["e745146f4a8fd844"] = { "Ramstein ha fame di carne!", "." },
  ["e7481573cf34ec28"] = { "Aiuto! Aiuto! Non lasciate che mi mangino!", "." },
  ["e74b11eb1a01a8c6"] = { "Ecco il tuo pane, signore.", "." },
  ["e74b5ea2b6c1854d"] = { "Ma cosa vuol dire allergico? E che c'entra con i miei due gattini?", "." },
  ["e754e5e573dbf608"] = { "Attaccami pure, se vuoi, ma non mi impedirai di tornare da Quae.", "." },
  ["e75e8fde5fd8b02a"] = { "Salute a te, {name}. Desideri che ti aiuti nel tuo viaggio verso la ⟦Warsong Gulch=Forra dei Cantaguerra⟧?", "." },
  ["e7601752dc3822cc"] = { "Ehi, {class}. Ho parlato con tutti qui intorno e pare che abbiamo tutta la roba che serve all'⟦Alliance=Alleanza⟧ per la guerra. Quell'antipatico ambasciatore orco ha detto che l'⟦Horde=Orda⟧ sta ancora raccogliendo, il che significa che abbiamo un po' di tempo prima di dover spedire tutto a ⟦Silithus=Silitus⟧.", "." },
  ["e765f00b2cb805f0"] = { "Tu! Sì, proprio tu! Hai l'aria di chi ha sete. Vieni qui, ho proprio quello che ti serve!", "." },
  ["e76f35779823bfc7"] = { "Grazie per il formaggio!", "." },
  ["e770e3f3492b087e"] = { "Per l'assimilazione di questi dati è essenziale comprendere che i Creatori volevano sintetizzare una razza che restasse a lungo parte integrante del ciclo di sviluppo di questo mondo dopo la loro partenza. Questa razza sarebbe stata determinante per realizzare gli obiettivi di sviluppo a lungo termine dei Creatori per Azeroth.\n\nCome nota accessoria, i Creatori ritennero appropriata per la nuova razza la denominazione «Terrigeni», in base alla composizione dei Terrigeni stessi.", "." },
  ["e77184475e894eb4"] = { "Ah, un tempo eri <un/una> <veterano/veterana> <esperto/esperta>. Kilram può farti tornare così. So che ne hai le capacità: devi solo chiedere e ti insegnerò la via del Fabbro d'Asce.", "." },
  ["e7797c2fb153044a"] = { "Portami alla ⟦Crown Guard Tower=Torre della Corona⟧.", "." },
  ["e782002f03bbc85a"] = { "Ti do il benvenuto, {class}. Di rado riceviamo visitatori quaggiù, a questi livelli dell'Apothecarium... a meno che, naturalmente, qualcuno non voglia qualcosa... o non ne abbia bisogno.\n\n<Il chimico Coely ride.>\n\nCome posso aiutarti oggi, eh?", "." },
  ["e7873cffb16b281d"] = { "Clicca qui per riparare l'equipaggiamento", "." },
  ["e79105c8c351d9c2"] = { "Dov'è l'istruttore di Incantamento?", "." },
  ["e79c286254878e00"] = { "Avanti, Crociati! Dobbiamo riprenderci il ⟦Corin's Crossing=Crocevia di Corin⟧!", "." },
  ["e7a3b36df071287c"] = { "Salute, {class}. Sono Miranda Breechlock, fra i pochi intendenti autorizzati per l'equipaggiamento e i materiali dell'Alba.\n\nMentre combatti il male per nostro incarico, guadagnandoti il nostro rispetto e la nostra fiducia, riceverai gettoni del valore dal duca Zverenhoff. I gettoni servono a due scopi: usali per migliorare la tua posizione tra i nostri ranghi, oppure come moneta per acquistare oggetti speciali.\n\nMan mano che migliorerai la tua posizione presso l'Alba, scoprirai che avrai a disposizione sempre più oggetti.", "." },
  ["e7ac0a9900cab08f"] = { "L'⟦Horde=Orda⟧ ha preso la fattoria!", "." },
  ["e7ae7b9d303826a3"] = { "Brzzzzt!\n\nTi do il benvenuto nel Matrix Punchograph 3005 barra B, un terminale con livello di sicurezza beta.\n\nPer accedere alle funzioni del terminale devi possedere una scheda perforata gialla.\n\n01000111 01101110 01101111 01101101 01100101 01110010 01100011 01111001 00100001", "." },
  ["e7b42382f2bea195"] = { "La vita non ha senso. È nella morte che veniamo messi davvero alla prova.", "." },
  ["e7ccb48d4c5277db"] = { "La East Frostwolf Tower è sotto attacco! Se nessuno interviene, l'⟦Alliance=Alleanza⟧ la distruggerà!", "." },
  ["e7d152ae28460455"] = { "Salute! Hai un'aria familiare... ci siamo già visti?\n\nBe', se ci siamo già visti, allora... di sicuro ti hanno dato un codice segreto. Dimmi il tuo codice e ti darò un regalo!", "." },
  ["e7d71cfdd6f877ae"] = { "Porta la Tattered Note a Veyric Thunderhame negli ⟦Arathi Highlands=Altopiani d'Arathi⟧.", "." },
  ["e7e95f422aef9215"] = { "Ci voleva proprio che i nani mandassero da ⟦Ironforge=Forgiardente⟧ un esperto di estrazione a spiegarci come si scava. Quanto sarà difficile prendere un piccone e scalpellare un po' di roccia? Be', visto che è qui, probabilmente è lui che dovresti andare a trovare. Si chiama Gelman e sta nel Distretto dei Nani.", "." },
})
